USE bodb_Account
GO

-- Step 1: Create new table
IF OBJECT_ID('bodb_Account.dbo.HNISettings') IS NOT NULL
BEGIN
	DROP TABLE dbo.HNISettings
END
GO

CREATE TABLE dbo.HNISettings (
	isDeposit BIT,
	OrderByProduct INT,
	OrderByFigure INT,
	ProductID INT,
	AliasProductID INT,	
	ProductPrefix VARCHAR(50),
	ProductCategory VARCHAR(50),
	ProductGroup VARCHAR(50),
	ProductName VARCHAR(50),
	ProductShortName VARCHAR(50),
	Figure VARCHAR(200),
	isEnable BIT,
	EndOfSupportDate DATE,
	LogicCode SMALLINT,
	LogicDescription VARCHAR(1000)
	
	CONSTRAINT AK_HNISettings UNIQUE (isDeposit, ProductShortName, Figure) ON [DATA]
) ON [DATA]
GO

